CREATE OR REPLACE FUNCTION public.guard_learning_progress_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NOT public.is_admin_user(auth.uid()) THEN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.lesson_id IS DISTINCT FROM OLD.lesson_id THEN RAISE EXCEPTION 'Learning progress identity is immutable'; END IF; IF NEW.progress_percent < OLD.progress_percent THEN RAISE EXCEPTION 'Learning progress cannot move backwards'; END IF; IF NEW.completed_at IS DISTINCT FROM OLD.completed_at AND OLD.completed_at IS NOT NULL THEN RAISE EXCEPTION 'Completed learning progress is immutable'; END IF; END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_guard_learning_progress_mutation ON public.student_lesson_progress; CREATE TRIGGER trg_guard_learning_progress_mutation BEFORE UPDATE ON public.student_lesson_progress FOR EACH ROW EXECUTE FUNCTION public.guard_learning_progress_mutation();
CREATE OR REPLACE FUNCTION public.guard_course_enrollment_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NOT public.is_admin_user(auth.uid()) THEN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.course_id IS DISTINCT FROM OLD.course_id THEN RAISE EXCEPTION 'Course enrollment identity is immutable'; END IF; IF NEW.progress_pct < OLD.progress_pct THEN RAISE EXCEPTION 'Course progress cannot move backwards'; END IF; IF OLD.completed_at IS NOT NULL AND NEW.completed_at IS DISTINCT FROM OLD.completed_at THEN RAISE EXCEPTION 'Completed enrollment is immutable'; END IF; END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_guard_course_enrollment_mutation ON public.course_enrollments; CREATE TRIGGER trg_guard_course_enrollment_mutation BEFORE UPDATE ON public.course_enrollments FOR EACH ROW EXECUTE FUNCTION public.guard_course_enrollment_mutation();
